CREATE TYPE public.app_role AS ENUM ('admin','user');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE NOT NULL,role public.app_role NOT NULL,UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_role ON public.user_roles FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated;
CREATE TABLE public.legal_library (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),kind text NOT NULL CHECK(kind IN ('ley','fallo','fuente')),title text NOT NULL,official_url text NOT NULL,content text NOT NULL DEFAULT '',reference text NOT NULL DEFAULT '',chamber text NOT NULL DEFAULT '',subject text NOT NULL DEFAULT '',decision_date date,reviewed_at timestamptz NOT NULL DEFAULT now(),published boolean NOT NULL DEFAULT false,created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.legal_library TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.legal_library TO authenticated; GRANT ALL ON public.legal_library TO service_role;
ALTER TABLE public.legal_library ENABLE ROW LEVEL SECURITY;
CREATE POLICY published_library ON public.legal_library FOR SELECT TO anon,authenticated USING (published);
CREATE POLICY admin_library ON public.legal_library FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE INDEX legal_library_kind_idx ON public.legal_library(kind,published,reviewed_at DESC);
CREATE TABLE public.legal_cases (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,title text NOT NULL,number text NOT NULL DEFAULT '',jurisdiction text NOT NULL DEFAULT '',court text NOT NULL DEFAULT '',district text NOT NULL DEFAULT '',status text NOT NULL DEFAULT 'Activo',risk text NOT NULL DEFAULT 'Sin evaluar',summary text NOT NULL DEFAULT '',people text NOT NULL DEFAULT '',official_url text NOT NULL DEFAULT 'https://www.csj.gov.py/portal',created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.legal_cases TO authenticated; GRANT ALL ON public.legal_cases TO service_role;
ALTER TABLE public.legal_cases ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_cases ON public.legal_cases FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE INDEX legal_cases_owner_idx ON public.legal_cases(user_id,created_at DESC);
CREATE TABLE public.case_entries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),case_id uuid NOT NULL REFERENCES public.legal_cases(id) ON DELETE CASCADE,kind text NOT NULL CHECK(kind IN ('actuacion','tarea','documento')),title text NOT NULL,body text NOT NULL DEFAULT '',due_date date,done boolean NOT NULL DEFAULT false,file_path text,official_url text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.case_entries TO authenticated; GRANT ALL ON public.case_entries TO service_role;
ALTER TABLE public.case_entries ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_case_entries ON public.case_entries FOR ALL TO authenticated USING(EXISTS(SELECT 1 FROM public.legal_cases c WHERE c.id=case_id AND c.user_id=auth.uid())) WITH CHECK(EXISTS(SELECT 1 FROM public.legal_cases c WHERE c.id=case_id AND c.user_id=auth.uid()));
CREATE INDEX case_entries_case_idx ON public.case_entries(case_id,created_at);
